(()=>{
"use strict";
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=(v)=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const STORE="tcc-lab-preview-v3";
const initial={lessons:{},w2:{introSeen:false,step:0,tabs:[],facts:[],connections:[],hypothesis:"",question:"",revision:"",revealChoice:"",twistRevealed:false,move:"",response:"",responseChoice:"",coachingRevealed:false,playbookSaved:false,history:[]},w3:{tab:"opening",opening:"",openingOwn:"",aim:"",middle:"",middleOwn:"",pivot:"",before:"",after:"",closing:[],closingOwn:""},w4:{tab:"notice",guideTab:"opening",notice:[],aim:"",missing:"",rationale:"",guide:{opening:"",middle:"",closing:""},guideOwn:{opening:"",middle:"",closing:""},adapt:"",adaptOwn:"",before:"",after:""},sims:{},reflections:{},practice:{},plan:{skill:"",schedule:"",material:"",measure:"",support:""},evidence:{notice:"",decide:"",guide:"",adapt:""}};
const merge=(a,b)=>{for(const k in b){if(b[k]&&typeof b[k]==="object"&&!Array.isArray(b[k])&&!(b[k] instanceof Set))a[k]=merge(a[k]||{},b[k]);else a[k]=b[k]}return a};
let state=merge(structuredClone(initial),JSON.parse(localStorage.getItem(STORE)||"{}"));
if(state.w2.tabs.length||state.w2.connections.length||state.w2.hypothesis)state.w2.introSeen=true;
const save=()=>{localStorage.setItem(STORE,JSON.stringify(state));updateProgress()};
const show=(name)=>{window.TCCShowCourseScreen?.(name);$$('[data-screen]').forEach(b=>b.classList.toggle('active',b.dataset.screen===name))};
const status=(root,msg="Saved privately in this preview.")=>{const el=$('.save-status',root);if(el)el.textContent=msg;save()};
const choose=(root,selector,current,onChoose)=>{$$(selector,root).forEach(b=>{b.classList.toggle('selected',current===b.dataset.value);b.onclick=()=>onChoose(current===b.dataset.value?"":b.dataset.value)})};
const multi=(root,selector,values,onChange)=>{$$(selector,root).forEach(b=>{b.classList.toggle('selected',values.includes(b.dataset.value));b.onclick=()=>{const v=b.dataset.value;values.includes(v)?values.splice(values.indexOf(v),1):values.push(v);onChange(values)}})};
const input=(root,selector,onChange)=>{$$(selector,root).forEach(x=>x.oninput=()=>{onChange(x.name,x.value);save()})};
const back=(week)=>`<button class="back-link" type="button" data-back-week="${week}">← Back to Week ${week}</button>`;
const head=(week,title,copy)=>`<header class="advanced-head"><div><p class="eyebrow">Week ${week}</p><h1>${title}</h1><p>${copy}</p></div></header>`;
const lesson=(week,n,title,description)=>`<div class="lesson-row"><span>${n}</span><div><h3>${title}</h3><p>${description}</p></div><button class="secondary" data-lesson="w${week}-${n}">${state.lessons[`w${week}-${n}`]?"Review":"Open lesson"}</button></div>`;
const weekData={
1:{title:"The Therapist Behind the Therapy",outcome:"Notice what happens under pressure, return your attention to the client, and choose one observable adjustment to practice.",lessons:[["Confidence Is Not a Personality Trait","Separate grounded clinical confidence from certainty or performance."],["Meet the Clinician Behind the Reaction","Notice the pressure, protective response, and attention shift happening inside the therapist."],["Use P.A.U.S.E. When You Go Blank","Create enough room to return to the client and choose a purposeful next move."]],lab:"Clinical Blind Spot Lab",labScreen:"w1-blind-spot",labCopy:"Practice separating what you observed, what you inferred, and what still needs clarification.",sim:"The Advice Request",simScreen:"case-advice",simCopy:"Respond to Jordan, receive new information, and revise your approach without hunting for a perfect line.",profile:"Clinical Confidence Profile",profileScreen:"w1-profile",profileCopy:"Turn your pressure patterns and practice evidence into one specific development target."},
2:{title:"Getting Unstuck in the Room",outcome:"Choose a next move based on client priorities, relevant context, uncertainty, and a defensible clinical purpose.",lessons:[["Find the Thread, Not Just the Topic","Separate client facts from hypotheses and check whether a pattern fits."],["CLEAR","Clarify, Locate, Embody, Act, then Reflect and Recalibrate."],["Choose a Move You Can Explain","Choose a purposeful response without hunting for one perfect sentence."]],lab:"Clinical Detective",labScreen:"w2-detective",sim:"The Client Who Brings Everything",simScreen:"w2-simulation",profile:"Clinical Decision-Making Map"},
3:{title:"From Conversation to Clinical Movement",outcome:"Guide the beginning, middle, and ending of a session while staying collaborative and responsive.",lessons:[["Begin With a Destination, Not a Script","Create a collaboratively chosen destination without rigid dialogue."],["Deepen or Shift? The Mid-Session Choice","Use purpose and new information to decide whether to stay or pivot."],["The Last Ten Minutes Still Matter","Land the session without forcing resolution or a breakthrough."]],lab:"Session Architect",labScreen:"w3-architect",sim:"The Session That Goes Sideways",simScreen:"w3-simulation",profile:"50-Minute Session Roadmap"},
4:{title:"Become a Clinician You Can Trust",outcome:"Integrate noticing, reasoning, purposeful guidance, and recalibration in a fresh fictional case.",lessons:[["Debrief the Choice, Not Your Worth","Separate observable information from global self-judgment."],["When Your Response Misses","Notice, inquire, acknowledge impact, and adjust from feedback."],["Build Confidence From Evidence","Use observable behavior to create a sustainable practice plan."]],lab:"Clinical Mastery Lab",labScreen:"w4-mastery",sim:"The Session That Challenges You",simScreen:"w4-simulation",profile:"Clinical Skills Showcase + Playbook"}
};
const weekVerb={1:"Notice",2:"Decide",3:"Guide",4:"Adapt"};
const weekDefaultCopy=(d,type)=>type==='lab'?`Complete the week’s interactive clinical reasoning lab. Your choices become evidence in your ${d.profile}.`:type==='sim'?`Step into a fictional session, choose a clinical direction, and see how the client responds.`:`Use the work you actually completed this week to update your ${d.profile}.`;
function weekSequence(week,d){return `<div class="week-sequence"><section class="sequence-block learn-block"><div class="sequence-number">01</div><div class="sequence-content"><p class="eyebrow">Learn</p><div class="sequence-title"><div><h2>Build the clinical foundation.</h2><p>Three focused teaching videos, kept together so the ideas build on one another.</p></div><span>3 lessons</span></div><div class="lesson-group">${d.lessons.map((x,i)=>lesson(week,i+1,x[0],x[1])).join("")}</div></div></section><section class="sequence-block"><div class="sequence-number">02</div><div class="sequence-content"><p class="eyebrow">Train</p><div class="sequence-action"><div><h2>${d.lab}</h2><p>${d.labCopy||weekDefaultCopy(d,'lab')}</p><small>Why it matters: practice turns the week’s ideas into observable clinical reasoning.</small></div><button class="primary" data-go-advanced="${d.labScreen}">Open the lab →</button></div></div></section><section class="sequence-block"><div class="sequence-number">03</div><div class="sequence-content"><p class="eyebrow">Simulate</p><div class="sequence-action"><div><h2>${d.sim}</h2><p>${d.simCopy||weekDefaultCopy(d,'sim')}</p><small>Why it matters: the client’s response gives you new information to work with.</small></div><button class="primary" data-go-advanced="${d.simScreen}">Enter simulation →</button></div></div></section><section class="sequence-block reflect-block"><div class="sequence-number">04</div><div class="sequence-content"><p class="eyebrow">Reflect &amp; Save</p><div class="sequence-action"><div><h2>${d.profile}</h2><p>${d.profileCopy||weekDefaultCopy(d,'profile')}</p><small>Why it matters: confidence grows from evidence you can revisit—not a score.</small></div><button class="secondary" ${week===1?`data-go-advanced="${d.profileScreen}"`:'data-open-playbook'}>Update my profile →</button></div></div></section></div>`}
const weekStage=[0,0,0,0,0];
const weekArt={1:'../assets/optimized/clinical-training-study-tools.jpg',2:'../assets/optimized/therapist-professional-development-workshop.jpg',3:'../assets/optimized/clinical-skills-workshop.jpg',4:'../assets/optimized/clinical-training-study-tools.jpg'};
const weekHeroTitle={1:'The Therapist Behind the <em>Therapy.</em>',2:'Getting Unstuck <em>in the Room.</em>',3:'From Conversation to <em>Clinical Movement.</em>',4:'Become a Clinician <em>You Can Trust.</em>'};
function stagePanel(week,d,stage){
 if(stage===0)return `<div class="course-stage-media"><img src="${weekArt[week]}" alt="Clinical learning materials arranged on a desk"></div><div class="course-stage-copy"><p class="eyebrow">Stage 1 · Watch · 3 lessons</p><h2>Three teaching lessons</h2><p>Short lessons that introduce the ideas you’ll practice this week.</p><div class="course-lesson-list">${d.lessons.map((x,i)=>{const on=state.lessons[`w${week}-${i+1}`];return `<button type="button" class="${on?'is-done':''}" data-lesson="w${week}-${i+1}"><span>${i+1}</span><strong>${x[0]}<em>${x[1]}</em></strong><small>${on?'Watched ✓':'Watch →'}</small></button>`}).join('')}</div><button type="button" class="course-then" data-go-advanced="${d.labScreen}">Then: ${d.lab} →</button></div>`;
 const stages=[null,{eyebrow:'Stage 2 · Train',title:d.lab,copy:d.labCopy||weekDefaultCopy(d,'lab'),label:'Open the lab',screen:d.labScreen},{eyebrow:'Stage 3 · Experience',title:d.sim,copy:d.simCopy||weekDefaultCopy(d,'sim'),label:'Enter simulation',screen:d.simScreen},{eyebrow:'Stage 4 · Create',title:d.profile,copy:d.profileCopy||weekDefaultCopy(d,'profile'),label:'Update my profile',screen:d.profileScreen},{eyebrow:'Stage 5 · Practice · Optional',title:`Week ${week} Practice Floor`,copy:`Short extra reps with this week’s skill. Come back any time.`,label:'Open this week’s reps',screen:'practice-floor'}];
 const x=stages[stage];return `<div class="course-stage-focus"><p class="eyebrow">${x.eyebrow}</p><h2>${x.title}</h2><p>${x.copy}</p><button class="primary" ${stage===3&&week!==1?'data-open-playbook':stage===4?`data-open-practice="${week}"`:`data-go-advanced="${x.screen}"`}>${x.label} →</button></div>`;
}
function renderWeek(week){const d=weekData[week],root=$(`[data-screen-panel="week-${week}"]`),stage=weekStage[week];const tabs=[['Watch','Three teaching lessons'],['Train',d.lab],['Experience',d.sim],['Create',d.profile],['Practice','Practice Floor']];root.innerHTML=`<div class="advanced-shell course-week-shell"><header class="course-week-hero"><button type="button" class="course-home-link" data-go-advanced="dashboard">← Course home</button><p class="eyebrow">Week ${week} of 4</p><h1>${weekHeroTitle[week]}</h1><p>${d.outcome}</p><span class="course-week-number" aria-hidden="true">0${week}</span></header><nav class="course-stage-strip" aria-label="Week ${week} stages">${tabs.map((x,i)=>`<button type="button" class="course-stage-tab ${stage===i?'active':''}" data-week-stage="${i}"><small>${i+1} · ${x[0]}${i===0&&lessonsDone(week)===3?' ✓':''}</small><strong>${x[1]}</strong>${i===4?'<span>Optional</span>':''}</button>`).join('')}</nav><section class="course-stage-panel ${stage===0?'is-watch':'is-focus'}">${stagePanel(week,d,stage)}</section></div>`;$$('[data-week-stage]',root).forEach(b=>b.onclick=()=>{weekStage[week]=Number(b.dataset.weekStage);renderWeek(week);commonBindings(root)});commonBindings(root)}
const lessonsDone=w=>[1,2,3].filter(n=>state.lessons[`w${w}-${n}`]).length;
const italLast=t=>{const m=String(t).match(/^(.*\s)(\S+)$/);return m?`${esc(m[1])}<em>${esc(m[2])}</em>`:esc(t)};
function nextStep(){for(const w of [1,2,3,4])for(const n of [1,2,3])if(!state.lessons[`w${w}-${n}`])return {w,n,title:weekData[w].lessons[n-1][0]};return null}
function renderUpNext(){const b=$('.redesign-next');if(!b)return;const nx=nextStep(),started=Object.values(state.lessons).some(Boolean);
 if(!started){b.dataset.go='start';b.removeAttribute('data-open-lesson');b.innerHTML='<span>Up next</span><strong>Start Here</strong><small>How the Lab works</small><b>→</b>';b.onclick=()=>show('start');return}
 if(!nx){b.innerHTML='<span>All lessons watched</span><strong>Your Playbook</strong><small>Everything you built, in one place</small><b>→</b>';b.onclick=()=>{renderPlaybook();show('playbook')};return}
 b.innerHTML=`<span>Up next · Week ${nx.w} · Lesson ${nx.n}</span><strong>${esc(nx.title)}</strong><small>${esc(weekData[nx.w].title)}</small><b>→</b>`;b.onclick=()=>{renderLesson(`w${nx.w}-${nx.n}`);show('lesson')}}
function renderWeeks(){const grid=$('[data-module-grid]'),cur=(nextStep()||{w:4}).w;if(grid)grid.innerHTML=[1,2,3,4].map(week=>{const d=weekData[week],done=lessonsDone(week),st=week<cur?'Lessons watched':week===cur?(done?`${done} of 3 lessons watched`:'You are here'):'Up ahead';return `<article class="module-card${week===cur?' is-current':''}"><span class="module-num" aria-hidden="true">0${week}</span><p class="eyebrow">Week ${week} · ${weekVerb[week]}</p><h3>${italLast(d.title)}</h3><p class="module-outcome">${d.outcome}</p><div class="module-foot"><span class="module-status">${st}</span><button class="secondary" data-go-advanced="week-${week}">Open week ${week} <span aria-hidden="true">→</span></button></div></article>`}).join('');for(const week of [1,2,3,4])renderWeek(week);renderUpNext()}
function commonBindings(root=document){$$('[data-go-advanced]',root).forEach(b=>b.onclick=()=>show(b.dataset.goAdvanced));$$('[data-back-week]',root).forEach(b=>b.onclick=()=>show(`week-${b.dataset.backWeek}`));$$('[data-open-playbook]',root).forEach(b=>b.onclick=()=>{renderPlaybook();show('playbook')});$$('[data-open-practice]',root).forEach(b=>b.onclick=()=>{renderPractice(Number(b.dataset.openPractice)||0);show('practice-floor')});$$('[data-lesson],[data-open-lesson]',root).forEach(b=>b.onclick=()=>{renderLesson(b.dataset.lesson||b.dataset.openLesson);show('lesson')})}

const w2Tabs={Work:"I keep missing deadlines. My manager keeps adding new responsibilities, and I hate disappointing them.",Sleep:"I replay conversations at night and wonder if people think I let them down.",Family:"My sibling says I take on too much. But I’m the one everyone calls when they need help.",Friends:"I have been declining invitations. I’m exhausted, and I feel guilty about that too."};
const w2Connections=["Fear of disappointing others","Overcommitment and exhaustion","Practical workload and resource strain","The concerns may not share one dominant thread"];
const w2Hyp=["Avery may fear disappointing people and overextend themself.","Avery may have more responsibilities than they can realistically manage.","There may not be one dominant process connecting every concern."];
const w2Qs=["What happens when you consider saying no to a request?","What demands are you carrying that others might not see?","Which of these concerns feels most important for today?"];
const w2Moves=[
 {label:"Clarify Avery’s immediate priority",example:"What would feel most useful for us to understand together today?",coach:"This keeps Avery in the lead and prevents the session from becoming a tour of every problem. Listen for what feels most urgent, meaningful, or workable—not merely the first topic named."},
 {label:"Explore a possible process",example:"I’m noticing how often disappointing someone seems to show up here. Would it fit to slow down and look at what happens when someone needs something from you?",coach:"Tentative language makes the pattern available without turning it into a verdict. Stay open to correction and avoid treating a relational pattern as the whole explanation."},
 {label:"Explore practical constraints",example:"Before we talk about changing anything, can we map what you are carrying and which responsibilities actually have room to move?",coach:"This honors the reality that Avery’s choices are constrained. Curiosity about resources, obligations, and consequences can prevent an overly individual explanation."},
 {label:"Offer a collaborative map",example:"Would it help if we sorted this into what feels urgent, what may be connected, and what needs more information before we decide where to begin?",coach:"A shared map can reduce overwhelm while preserving complexity. Check whether organizing feels helpful to Avery rather than assuming structure is what they need."}
];
const w2Stages=["Get to Know Avery","What’s the Thread?","Working Theory","The Plot Twist","Your Next Move","Thinking Map"];
const w2RevisionOptions=["Keep the original theory, but hold it more lightly.","Revise the theory to include real financial and relational constraints.","Pause theory-building and clarify what Avery needs from today’s session."];
const w2Icons={Work:"▤",Sleep:"☾",Family:"⌂",Friends:"◌"};
function w2Board(s){return `<aside class="detective-board" aria-label="Avery’s case"><div class="board-discoveries">${Object.keys(w2Tabs).map(k=>`<button type="button" aria-label="${k}${s.tabs.includes(k)?' explored':''}" data-jump-discovery="${k}" class="${s.tabs.includes(k)?'found':''}"><i>${w2Icons[k]}</i><span>${k}</span></button>`).join('')}</div>${s.connections.length?`<div class="board-thread"><span>Possible thread</span><strong>${esc(s.connections[0])}</strong></div>`:''}</aside>`}
function w2StageRail(s){return `<nav class="detective-rail" aria-label="Clinical Detective stages">${w2Stages.map((x,i)=>`<button type="button" data-w2-stage="${i}" class="${s.step===i?'active':''} ${i<s.step?'complete':''}" ${i>s.step+1?'disabled':''}><b>${i+1}</b><span>${x}</span></button>`).join('')}</nav>`}
function w2Shell(s,content){if(!s.introSeen)return `<div class="advanced-shell detective-shell">${back(2)}${content}</div>`;return `<div class="advanced-shell detective-shell">${back(2)}<header class="detective-page-head"><div><p class="eyebrow">Clinical Detective · Case 01</p><h1>Four Problems. Where Do You Start?</h1></div><p>A clinical reasoning experience with Avery</p></header>${w2StageRail(s)}<div class="detective-layout">${w2Board(s)}<main class="detective-main">${content}<p class="save-status" aria-live="polite"></p></main></div></div>`}
function renderW2(){const root=$('[data-advanced-host="w2-detective"]'),s=state.w2;s.step=Math.min(5,Math.max(0,s.step));let body="";
if(!s.introSeen)body=`<section class="detective-welcome"><div class="welcome-case"><p class="eyebrow">Clinical Detective · Case 01</p><h1>Four Problems.<br>Where Do You Start?</h1><p class="case-subtitle">A clinical reasoning experience</p><div class="client-intro"><span class="client-avatar">A</span><div><h2>Meet Avery, 31.</h2><p>Avery has been coming to therapy for anxiety and stress. It’s your third session together.</p><p>Today, Avery starts talking about several different problems.</p></div></div><blockquote>“Work is a mess. I’m barely sleeping. My sister’s upset with me, and I keep canceling on my friends. I feel like I’m failing at everything, and I don’t even know where to start.”</blockquote></div><div class="welcome-challenge"><p class="eyebrow">Your Challenge</p><h2>Listen for what might connect.</h2><p>Avery has brought you four different concerns.</p><p>Your job isn’t to solve all four. It’s to figure out what might connect them, what you still need to understand, and where you’d take the conversation next.</p><h3>What you’ll practice</h3><ul><li>Explore Avery’s story</li><li>Look for a possible thread</li><li>Discover new information</li><li>Decide what you’d actually say</li></ul><button type="button" class="primary" data-begin-investigation>Begin the Investigation →</button></div></section>`;
if(s.introSeen&&s.step===0)body=`<section class="detective-stage"><div class="stage-intro"><p class="eyebrow">Stage 1 · Get to Know Avery</p><h2>You Can’t Explore Everything at Once.</h2><p>Where would you get curious first?</p></div><div class="discovery-grid">${Object.keys(w2Tabs).map(k=>`<button type="button" class="discovery-card ${s.tabs.includes(k)?'discovered':''}" data-context="${k}"><span class="discovery-icon">${w2Icons[k]}</span><span><small>${s.tabs.includes(k)?'Discovered':'Explore'}</small><strong>${k}</strong></span><i>${s.tabs.includes(k)?'✓':'+'}</i></button>`).join('')}</div>${s.activeTab?`<article class="client-message reveal-in"><div class="client-avatar">A</div><div><p><strong>Avery</strong> · about ${s.activeTab.toLowerCase()}</p><blockquote>“${w2Tabs[s.activeTab]}”</blockquote><small>Added to your case notes.</small></div></article>`:`<div class="discovery-empty"><span>Choose any area to hear more from Avery.</span></div>`}<div class="stage-prompt"><strong>There is no clinically “correct” order.</strong><span>Explore all four areas before you look for a thread. The order you choose is simply where your curiosity begins.</span></div>${w2Nav(s,s.tabs.length===4,'Look for a thread →') }</section>`;
if(s.step===1)body=`<section class="detective-stage"><div class="stage-intro"><p class="eyebrow">Stage 2 · What’s the Thread?</p><h2>What might connect what you’ve heard?</h2><p>Move between the evidence and possible connections. More than one interpretation can be clinically reasonable.</p></div><div class="evidence-canvas"><div class="evidence-stack">${s.facts.map((k,i)=>`<article class="evidence-card" style="--delay:${i*70}ms"><span>${w2Icons[k]} ${k}</span><p>“${esc(w2Tabs[k])}”</p></article>`).join('')}</div><div class="connection-hub"><span>Possible connections</span><div class="thread-options">${w2Connections.map(x=>`<button type="button" data-thread data-value="${esc(x)}" class="${s.connections.includes(x)?'selected':''}"><i></i>${x}</button>`).join('')}</div></div></div><p class="notice">A connection is something to explore with Avery—not an answer hidden in the case. Select any that seem worth holding in mind.</p>${w2Nav(s,s.connections.length>0,'Hold a working theory →')}</section>`;
if(s.step===2)body=`<section class="detective-stage"><div class="stage-intro"><p class="eyebrow">Stage 3 · What’s Your Working Theory?</p><h2>Choose a theory you would be willing to revise.</h2><p>What might be useful to explore next?</p></div><div class="theory-grid">${w2Hyp.map((x,i)=>`<button type="button" aria-pressed="${s.hypothesis===x}" data-hyp data-value="${esc(x)}" class="theory-card ${s.hypothesis===x?'selected':''}"><span>Possibility ${i+1}</span><strong>${x}</strong></button>`).join('')}</div><div class="clarify-panel ${s.hypothesis?'ready':''}"><p class="eyebrow">What would help you check it?</p><h3>Choose one question for Avery.</h3><div class="question-chips">${w2Qs.map(x=>`<button type="button" data-q data-value="${esc(x)}" class="${s.question===x?'selected':''}">${x}</button>`).join('')}</div>${s.question?`<div class="educator-note reveal-in"><strong>Why this helps</strong><p>This gives Avery room to confirm, complicate, or correct your thinking.</p></div>`:''}</div>${w2Nav(s,Boolean(s.hypothesis&&s.question),'See what Avery adds →')}</section>`;
if(s.step===3)body=`<section class="detective-stage"><div class="stage-intro"><p class="eyebrow">Stage 4 · The Plot Twist</p><h2>Avery adds something important.</h2><p>Good clinical reasoning changes when the context changes.</p></div>${!s.twistRevealed?`<button type="button" class="twist-envelope" data-reveal-twist><span>New message from Avery</span><strong>Open the new context</strong><i>→</i></button>`:`<div class="twist-reveal reveal-in"><div class="client-message"><div class="client-avatar">A</div><div><p><strong>Avery</strong> · adds context</p><blockquote>“I can’t just stop working extra hours. My mom needs financial help, and I’m paying for most of it. I’m scared of what happens if I say no.”</blockquote></div></div><div class="before-after"><article><span>What you were holding</span><p>${esc(s.hypothesis)}</p></article><i>→</i><article><span>What the new context asks you to reconsider</span><p>Choice, responsibility, feasibility, and the consequences of saying no.</p></article></div><h3 class="update-question">How does this change the way you understand Avery?</h3><div class="update-options">${w2RevisionOptions.map(x=>`<button type="button" data-update data-value="${esc(x)}" class="${s.revealChoice===x?'selected':''}">${x}</button>`).join('')}</div>${s.revealChoice?`<div class="clinical-nuance reveal-in"><p class="eyebrow">Clinical nuance</p><p>Real financial and relational constraints can change what is feasible. Avery’s exhaustion may involve a relational pattern, a practical burden, or both. Avoid reducing the story to “poor boundaries.”</p></div>`:''}</div>`}${w2Nav(s,Boolean(s.twistRevealed&&s.revealChoice),'Choose your next move →')}</section>`;
if(s.step===4){const chosen=w2Moves.find(x=>x.label===s.move);body=`<section class="detective-stage"><div class="stage-intro"><p class="eyebrow">Stage 5 · Your Next Move</p><h2>What direction would you take with Avery?</h2><p>Each option can be clinically reasonable. Choose the direction that best fits what you are trying to understand or accomplish.</p></div><div class="move-grid">${w2Moves.map((x,i)=>`<button type="button" data-move data-value="${esc(x.label)}" class="move-card ${s.move===x.label?'selected':''}"><span>Direction ${i+1}</span><strong>${x.label}</strong><small>${x.example}</small></button>`).join('')}</div>${chosen?`<div class="response-practice reveal-in"><p class="eyebrow">Practice the actual moment</p><h3>What would you say to Avery?</h3><p>Use the starter, adapt it, write your own, or rehearse privately. Typing is optional.</p><div class="response-tools"><button type="button" data-use-example class="secondary">Use the example as a starting point</button><button type="button" data-private-practice class="secondary ${s.responseChoice==='private'?'selected':''}">I practiced it privately</button></div><textarea name="response" placeholder="What I might say…">${esc(s.response)}</textarea><button type="button" class="coach-toggle" data-coaching ${!s.response.trim()&&s.responseChoice!=='private'?'disabled':''}>${s.coachingRevealed?'Hide educator coaching':'See educator coaching and an example'} <span>↓</span></button>${s.coachingRevealed?`<div class="coaching-panel reveal-in"><div><span>Why this direction may fit</span><p>${chosen.coach}</p></div><div><span>Example language</span><blockquote>“${chosen.example}”</blockquote><button type="button" data-use-example class="text-link">Adapt this example in my response</button></div></div>`:''}</div>`:''}${w2Nav(s,Boolean(s.move&&(s.response.trim()||s.responseChoice==='private')),'Build my thinking map →')}</section>`}
if(s.step===5)body=`<section class="detective-stage map-stage"><div class="stage-intro"><p class="eyebrow">Stage 6 · Your Clinical Thinking Map</p><h2>Here is how your reasoning moved.</h2><p>This is a record of your process, not a competence score. Every section stays editable.</p></div><div class="thinking-map"><header><div><span>Avery · Week 2</span><h3>From information to a purposeful next move</h3></div><b>${s.tabs.length} discoveries</b></header><div class="map-path"><article><button type="button" data-edit-stage="0">Edit</button><span>1 · What I discovered</span><ul>${s.facts.map(k=>`<li><strong>${k}:</strong> ${esc(w2Tabs[k])}</li>`).join('')}</ul></article><article><button type="button" data-edit-stage="1">Edit</button><span>2 · Threads I held in mind</span><p>${s.connections.map(esc).join(' · ')}</p></article><article><button type="button" data-edit-stage="2">Edit</button><span>3 · My working theory</span><p>${esc(s.hypothesis)}</p><small>I wanted to clarify: ${esc(s.question)}</small></article><article class="map-turn"><button type="button" data-edit-stage="3">Edit</button><span>4 · What changed the picture</span><p>Avery’s financial responsibility to their mother complicated the idea that they could simply set a limit.</p><strong>${esc(s.revealChoice)}</strong></article><article><button type="button" data-edit-stage="4">Edit</button><span>5 · My next clinical move</span><p><strong>${esc(s.move)}</strong></p><blockquote>${s.responseChoice==='private'?'Response rehearsed privately.':`“${esc(s.response)}”`}</blockquote></article></div><footer><p><strong>What this map shows:</strong> You gathered information, noticed possible connections, held a theory tentatively, updated it when the context changed, and chose language with a clinical purpose.</p><button type="button" class="primary" data-save-map>${s.playbookSaved?'Saved to my Playbook ✓':'Save to my Clinical Playbook'}</button></footer></div><div class="advanced-actions"><button class="secondary" data-retry>Try another path</button><button class="secondary" data-go-advanced="w2-simulation">Continue to Simulation Room</button></div></section>`;
root.innerHTML=w2Shell(s,body);$('[data-begin-investigation]',root)?.addEventListener('click',()=>{s.introSeen=true;s.step=0;save();renderW2()});bindW2(root);enableW2Toggles(root,s);commonBindings(root)}
function w2Nav(s,enabled,label){return `<div class="step-nav detective-nav">${s.step?'<button class="secondary" type="button" data-prev>← Previous stage</button>':'<span></span>'}<button class="primary" type="button" data-next ${enabled?'':'disabled'}>${label}</button></div>`}
function enableW2Toggles(root,s){$$('[data-context]',root).forEach(button=>button.onclick=()=>{const value=button.dataset.context;if(s.activeTab===value){s.activeTab=""}else{s.activeTab=value;if(!s.tabs.includes(value))s.tabs.push(value);if(!s.facts.includes(value))s.facts.push(value)}save();renderW2()})}
function bindW2(root){const s=state.w2;$('[data-next]',root)?.addEventListener('click',()=>{s.step=Math.min(5,s.step+1);save();renderW2()});$('[data-prev]',root)?.addEventListener('click',()=>{s.step=Math.max(0,s.step-1);save();renderW2()});$$('[data-w2-stage]',root).forEach(b=>b.onclick=()=>{s.step=Number(b.dataset.w2Stage);save();renderW2()});$$('[data-context]',root).forEach(b=>b.onclick=()=>{s.activeTab=b.dataset.context;if(!s.tabs.includes(s.activeTab))s.tabs.push(s.activeTab);if(!s.facts.includes(s.activeTab))s.facts.push(s.activeTab);save();renderW2()});$$('[data-jump-discovery]',root).forEach(b=>b.onclick=()=>{s.step=0;s.activeTab=b.dataset.jumpDiscovery;save();renderW2()});$$('[data-thread]',root).forEach(b=>b.onclick=()=>{const v=b.dataset.value;s.connections.includes(v)?s.connections.splice(s.connections.indexOf(v),1):s.connections.push(v);save();renderW2()});choose(root,'[data-hyp]',s.hypothesis,v=>{s.hypothesis=v;save();renderW2()});choose(root,'[data-q]',s.question,v=>{s.question=v;save();renderW2()});$('[data-reveal-twist]',root)?.addEventListener('click',()=>{s.twistRevealed=true;save();renderW2()});choose(root,'[data-update]',s.revealChoice,v=>{s.revealChoice=v;s.revision=v;save();renderW2()});choose(root,'[data-move]',s.move,v=>{s.move=v;s.coachingRevealed=false;save();renderW2()});input(root,'textarea',(k,v)=>s[k]=v);$$('[data-use-example]',root).forEach(b=>b.onclick=()=>{const chosen=w2Moves.find(x=>x.label===s.move);if(chosen)s.response=chosen.example;s.responseChoice='typed';save();renderW2()});$('[data-private-practice]',root)?.addEventListener('click',()=>{s.responseChoice='private';save();renderW2()});$('[data-coaching]',root)?.addEventListener('click',()=>{s.coachingRevealed=!s.coachingRevealed;save();renderW2()});$$('[data-edit-stage]',root).forEach(b=>b.onclick=()=>{s.step=Number(b.dataset.editStage);save();renderW2()});$('[data-save-map]',root)?.addEventListener('click',()=>{s.playbookSaved=true;status(root,'Clinical Thinking Map saved to your Clinical Playbook.');renderW2()});$('[data-retry]',root)?.addEventListener('click',()=>{s.history.push({tabs:[...s.tabs],facts:[...s.facts],connections:[...s.connections],hypothesis:s.hypothesis,question:s.question,revealChoice:s.revealChoice,move:s.move,response:s.response,at:new Date().toISOString()});s.step=1;s.connections=[];s.hypothesis=s.question=s.revealChoice=s.revision=s.move=s.response=s.responseChoice="";s.twistRevealed=s.coachingRevealed=s.playbookSaved=false;save();renderW2()})}

const simGraphs={
w2:{title:"The Client Who Brings Everything",client:"Avery",start:"AV-00",nodes:{"AV-00":["I barely slept. My boss is irritated with me, my sister isn’t talking to me, and I canceled on my friends. I don’t even know where to start.",[["Clarify priority","AV-10"],["Reflect overwhelm","AV-11"],["Test connection","AV-12"]]],"AV-10":["Maybe work? But honestly the family thing is what keeps me up.",[["Explore family pressure","AV-20"],["Ask what would make today useful","AV-21"]]],"AV-11":["It is overwhelming. And I’m irritated because I keep making it worse.",[["Clarify ‘making it worse’","AV-20"],["Explore impact of overwhelm","AV-21"]]],"AV-12":["I guess? I don’t know if all of it is connected though.",[["Accept correction and ask what matters most","AV-21"],["Explain hypothesis tentatively","AV-20"]]],"AV-20":["My family expects me to handle everything. If I don’t, someone gets hurt or angry.",[["Explore feasibility and context","AV-30"],["Explore emotional meaning","AV-31"]]],"AV-21":["I’d like to leave feeling like there’s something I can actually do. But not another list of things I’m failing at.",[["Clarify what feels manageable","AV-30"],["Acknowledge frustration and collaborate","AV-31"]]],"AV-30":["It’s not as simple as saying no. I help pay my mom’s bills.",[["Update plan around actual constraints","AV-40"],["Ask for concrete options Avery controls","AV-41"]]],"AV-31":["I feel guilty even thinking about setting limits. But I’m exhausted.",[["Explore guilt within context","AV-40"],["Collaboratively identify immediate priority","AV-41"]]],"AV-40":["Yes. I need someone to understand that I can’t just drop everything.",[["Continue","AV-50"]]],"AV-41":["That might help. I guess I’m scared of making things worse.",[["Continue","AV-50"]]],"AV-50":["So how do we work on this without pretending I have choices I don’t actually have?",[]]}},
w3:{title:"The Session That Goes Sideways",client:"Morgan",start:"MO-00",nodes:{"MO-00":["Every single time I try to contribute, someone cuts me off. Then I spend hours replaying it.",[["Explore meaning","MO-10"],["Clarify focus","MO-11"],["Reflect emotion","MO-12"]]],"MO-10":["It makes me feel invisible. Like my thoughts don’t matter.",[["Deepen meaning","MO-20"],["Ask what Morgan wants today","MO-21"]]],"MO-11":["I want to stop going home furious. But I also need to get this off my chest.",[["Make room for processing","MO-20"],["Collaborate on an eventual shift","MO-21"]]],"MO-12":["Yes, I’m furious. And honestly, I just want to vent.",[["Allow space then check usefulness","MO-20"],["Invite permission to connect to goal","MO-21"]]],"MO-20":["I know I’m going in circles. I just need you to understand how humiliating it feels.",[["Reflect emotional meaning","MO-30"],["Offer collaborative transition","MO-31"]]],"MO-21":["Maybe we can practice what to say, but please don’t make it another lecture.",[["Agree on one small rehearsal","MO-30"],["Clarify what would make rehearsal useful","MO-31"]]],"MO-30":["Actually, when I speak up my supervisor has retaliated with worse shifts.",[["Reassess constraints and feasibility","MO-40"],["Clarify workplace context","MO-41"]]],"MO-31":["I’m not sure it’s safe to push back at work. My shifts depend on it.",[["Reassess constraints and feasibility","MO-40"],["Clarify workplace context","MO-41"]]],"MO-40":["Thank you. Everyone keeps telling me to be more assertive, but it feels like they don’t get it.",[["Practice a response","MO-50"]]],"MO-41":["I could probably practice outside work first, but I’d need to figure out what’s realistic.",[["Practice a response","MO-50"]]],"MO-50":["We’re almost out of time. I don’t feel like we solved anything.",[["Validate and check meaning","MO-60"],["Summarize and collaborate on next step","MO-61"]]],"MO-60":["I guess I mostly wanted someone to see why this is so hard.",[]],"MO-61":["Okay. I want to keep working on it, just without pretending it’s simple.",[]]}},
w4:{title:"The Session That Challenges You",client:"Riley",start:"FS-0",nodes:{"FS-0":["I keep showing up here, and I don’t feel like anything has changed. I’m starting to wonder if any of this is helping.",[["Practice an open response","FS-1"]]],"FS-1":["We talk about the same problems. I understand them, but I don’t know what I’m supposed to do differently.",[["Clarify what Riley hoped would change","FS-2-A"],["Explore patterns and barriers","FS-2-B"],["Review treatment approach together","FS-2-C"]]],"FS-2-A":["I thought I’d stop shutting down whenever someone is upset with me.",[["Explore shutdown context","FS-3"],["Agree on a manageable practice target","FS-3"]]],"FS-2-B":["I know the pattern. I can tell you exactly what I do, and then I do it again.",[["Explore barriers and context","FS-3"],["Review fit of treatment approach","FS-3"]]],"FS-2-C":["I guess I never really knew what progress was supposed to look like.",[["Clarify goals together","FS-3"],["Review feedback about sessions","FS-3"]]],"FS-3":["When you ask me to do more worksheets, it feels like you’re not hearing me.",[["Practice a repair response","FS-4"]]],"FS-4":["I’m juggling work and my family. I’m overwhelmed when I leave here with another list.",[["Co-create a smaller next step","FS-5"],["Focus on processing what is possible","FS-5"],["Review treatment priorities","FS-5"]]],"FS-5":["Okay. I still don’t know if this is helping, but I do want us to try something different.",[]]}}
};
function renderSim(key){const cfg=simGraphs[key],week=Number(key.slice(1)),root=$(`[data-advanced-host="w${week}-simulation"]`),run=state.sims[key]||(state.sims[key]={node:cfg.start,path:[],responses:{},mode:"type",complete:false}),node=cfg.nodes[run.node],terminal=!node[1].length,openMoment=terminal||['FS-0','FS-3','FS-5','MO-40','MO-41','MO-60','MO-61','AV-50'].includes(run.node);root.innerHTML=`<div class="advanced-shell">${back(week)}${head(week,cfg.title,`Choose a direction, notice what changes, and adjust your response.`)}<article class="simulation-stage"><div class="simulation-media"><blockquote>“${node[0]}”</blockquote></div><div class="path-trail">${run.path.map((p,i)=>`<span>${i+1}. ${esc(p.choice)}</span>`).join('')||'<span>Session start</span>'}</div>${openMoment?responseBox(key,run):''}${!terminal?`<div class="choice-list">${node[1].map(([label,next])=>`<button data-sim-choice="${esc(label)}" data-next-node="${next}">${label}</button>`).join('')}</div>`:`<div class="profile-output"><p class="eyebrow">Debrief</p><h2>Review the path you took.</h2><p>What were you trying to accomplish? What changed? What information might have changed your choice?</p><button class="primary" data-finish-sim>Save this path</button></div>`}<div class="advanced-actions"><button class="secondary" data-restart-sim>Try another route</button></div><p class="save-status"></p></article></div>`;bindSim(root,key,cfg,run);commonBindings(root)}
function responseBox(key,run){const value=run.responses[run.node]||"";return `<div class="advanced-card"><p class="eyebrow">Your turn</p><h3>How would you respond?</h3><div class="response-modes"><button class="${run.mode==='type'?'active':''}" data-mode="type">Write it</button><button class="${run.mode==='private'?'active':''}" data-mode="private">Say it out loud</button></div>${run.mode==='type'?`<textarea data-sim-response placeholder="Write what you would actually say…">${esc(value)}</textarea>`:'<div class="placeholder-recorder"><p>Practice your response out loud, then continue when you’re ready.</p></div>'}</div>`}
function bindSim(root,key,cfg,run){$$('[data-mode]',root).forEach(b=>b.onclick=()=>{run.mode=b.dataset.mode;save();renderSim(key)});$('[data-sim-response]',root)?.addEventListener('input',e=>{run.responses[run.node]=e.target.value;save()});$$('[data-sim-choice]',root).forEach(b=>b.onclick=()=>{run.path.push({node:run.node,choice:b.dataset.simChoice,next:b.dataset.nextNode});run.node=b.dataset.nextNode;save();renderSim(key)});$('[data-finish-sim]',root)?.addEventListener('click',()=>{run.complete=true;status(root,'Simulation path saved to your practice history.');renderPlaybook()});$('[data-restart-sim]',root)?.addEventListener('click',()=>{state.sims[key]={node:cfg.start,path:[],responses:{},mode:'type',complete:false};save();renderSim(key)})}

const w3Choices={opening:["Listen briefly, then clarify today’s priority","Connect to the agreed broader goal","Offer processing or rehearsal as possible directions"],middle:["DEEPEN — What part of this has stayed with you most?","SUMMARIZE / CHECK — Is that the part we should stay with?","SHIFT COLLABORATIVELY — Practice a response or stay with the feeling?"],pivot:["Clarify workplace consequences and safety/context","Validate constraints and reassess what change is feasible","Revisit processing versus action","Identify another focus Morgan chooses"],closing:["Acknowledge","Summarize","Check","Plan"]};
function renderW3(){const root=$('[data-advanced-host="w3-architect"]'),s=state.w3,t=s.tab;let panel='';if(t==='opening')panel=`<h2>Opening · 0–10 minutes</h2><blockquote>“You will not believe what my coworker did.”</blockquote><p>What would make this time useful?</p>${choiceButtons(w3Choices.opening,s.opening)}<label>My own opening / clinical purpose<textarea name="openingOwn">${esc(s.openingOwn)}</textarea></label><button class="primary" data-set-aim>Set working destination</button>`;if(t==='middle')panel=`<h2>Middle · 10–40 minutes</h2><div class="context-reveal"><p>At minute 25: “I keep going over every detail because I’m so angry. Honestly, I just needed to vent today.”</p></div>${choiceButtons(w3Choices.middle,s.middle)}<div class="context-reveal"><p>New information: “When I do speak up, my manager sometimes punishes me with worse shifts.”</p></div><label>What needs to change in your plan?<textarea name="after">${esc(s.after)}</textarea></label>`;if(t==='pivot')panel=`<h2>Pivot builder</h2><div class="two-panel"><section><h3>Original plan</h3><textarea name="before">${esc(s.before)}</textarea></section><section><h3>Adjusted plan</h3><textarea name="after">${esc(s.after)}</textarea></section></div>${choiceButtons(w3Choices.pivot,s.pivot)}`;if(t==='closing')panel=`<h2>Closing · 40–50 minutes</h2><blockquote>“I guess I understand why I freeze. I just don’t know how I’m supposed to change it.”</blockquote><p>Select the blocks you would use.</p><div class="closing-builder">${w3Choices.closing.map(x=>`<label><input type="checkbox" value="${x}" ${s.closing.includes(x)?'checked':''}> <span><strong>${x}</strong> — ${({Acknowledge:'It makes sense that this feels complicated.',Summarize:'Today we noticed the costs and fears that come up when you consider speaking up.',Check:'Does that capture what mattered, or am I missing something?',Plan:'What would feel manageable to carry forward from today?'})[x]}</span></label>`).join('')}</div><label>My 20-second closing line<textarea name="closingOwn">${esc(s.closingOwn)}</textarea></label>`;if(t==='review')panel=`<h2>Review your session</h2><div class="review-grid"><section><h3>Opening</h3><p>${esc(s.aim||s.openingOwn||s.opening)}</p></section><section><h3>Middle</h3><p>${esc(s.middle)}</p><p><strong>Adjustment:</strong> ${esc(s.after)}</p></section><section><h3>Closing</h3><p>${s.closing.map(esc).join(' → ')}</p><p>${esc(s.closingOwn)}</p></section><section><h3>What remained collaborative?</h3><textarea name="collaborative">${esc(s.collaborative||'')}</textarea></section></div><button class="primary" data-save-roadmap>Save my Session Roadmap</button>`;root.innerHTML=`<div class="advanced-shell">${back(3)}${head(3,'Session Architect','Build a session map, then adjust it when the client gives you new information.')}<div class="session-compass"><span>Current focus</span><strong>${esc(s.aim||'Choose an opening below')}</strong></div><div class="timeline-tabs">${[['opening','Opening · 0–10'],['middle','Middle · 10–40'],['pivot','Pivot'],['closing','Closing · 40–50'],['review','Review']].map(([k,l])=>`<button data-w3-tab="${k}" class="${t===k?'active':''}">${l}</button>`).join('')}</div><article class="tab-panel">${panel}<p class="save-status"></p></article></div>`;bindW3(root);commonBindings(root)}
const choiceButtons=(items,current)=>`<div class="choice-list">${items.map(x=>`<button data-value="${esc(x)}" class="${current===x?'selected':''}">${x}</button>`).join('')}</div>`;
function bindW3(root){const s=state.w3;$$('[data-w3-tab]',root).forEach(b=>b.onclick=()=>{s.tab=b.dataset.w3Tab;save();renderW3()});if(['opening','middle','pivot'].includes(s.tab))choose(root,'.choice-list button',s[s.tab],v=>{s[s.tab]=v;save();renderW3()});input(root,'textarea',(k,v)=>s[k]=v);$('[data-set-aim]',root)?.addEventListener('click',()=>{s.aim=s.openingOwn||s.opening;status(root);renderW3()});$$('.closing-builder input',root).forEach(x=>x.onchange=()=>{x.checked?s.closing.push(x.value):s.closing.splice(s.closing.indexOf(x.value),1);save()});$('[data-save-roadmap]',root)?.addEventListener('click',()=>status(root,'Session Roadmap added to your Clinical Playbook.'))}

const w4Options={notice:["Observation: Maya understands some patterns but feels change is not occurring.","Hypothesis: Maya may be discouraged about therapy’s usefulness.","Hypothesis: Maya may need a different type of clinical work or clearer goals.","Therapist pressure: urge to defend therapy or rush into a technique."],decide:["Explore what feels unchanged for Maya","Clarify desired changes and treatment expectations","Investigate barriers and external constraints","Check the therapeutic relationship and whether the approach is fitting"],opening:["Acknowledge concern and clarify meaning","Review what Maya hoped would change","Collaboratively agree on the session focus"],middle:["Explore what happens before saying yes","Identify environmental constraints","Consider a small targeted rehearsal with consent","Return to clarifying what Maya needs"],closing:["Collaborative summary","Agree on one realistic experiment","Revisit the treatment plan","Set an appropriate follow-up or consultation plan"],adapt:["Acknowledge mismatch and ask what was missed","Explore practical constraints before suggesting behavior change","Collaboratively reconsider today’s focus and treatment approach"]};
function renderW4(){const root=$('[data-advanced-host="w4-mastery"]'),s=state.w4,t=s.tab;let p='';if(t==='notice')p=`<h2>NOTICE</h2><blockquote>“I understand why I do what I do, but I keep ending up in the same place. I’m starting to wonder whether therapy is helping.”</blockquote><p>Separate observable cues, provisional hypotheses, and therapist pressure.</p>${choiceButtons(w4Options.notice,'')}<label>My own observation, hypothesis, or pressure cue<textarea name="noticeOwn">${esc(s.noticeOwn||'')}</textarea></label>`;if(t==='decide')p=`<h2>DECIDE</h2><h3>One defensible next move</h3>${choiceButtons(w4Options.decide,s.aim)}<label>What do we still need to understand?<textarea name="missing">${esc(s.missing)}</textarea></label><label>I’d begin here because…<textarea name="rationale">${esc(s.rationale)}</textarea></label>`;if(t==='guide')p=`<h2>GUIDE</h2><div class="subtabs">${['opening','middle','closing'].map(k=>`<button data-guide-tab="${k}" class="${s.guideTab===k?'active':''}">${k}</button>`).join('')}</div><blockquote>“${s.guideTab==='opening'?'I want to know why nothing changes.':s.guideTab==='middle'?'I know I avoid conflict, but I still say yes to everyone.':'I don’t want another week where I understand everything but do nothing differently.'}”</blockquote>${choiceButtons(w4Options[s.guideTab],s.guide[s.guideTab])}<label>My ${s.guideTab} language or purpose<textarea name="guideOwn">${esc(s.guideOwn[s.guideTab])}</textarea></label>`;if(t==='adapt')p=`<h2>ADAPT</h2><div class="context-reveal"><p>“I don’t need another coping strategy. I need you to understand that I’m exhausted and barely have a choice about what I take on.”</p></div>${choiceButtons(w4Options.adapt,s.adapt)}<label>My own adjustment<textarea name="adaptOwn">${esc(s.adaptOwn)}</textarea></label><div class="two-panel"><section><h3>Before feedback</h3><textarea name="before">${esc(s.before)}</textarea></section><section><h3>After feedback</h3><textarea name="after">${esc(s.after)}</textarea></section></div>`;if(t==='review')p=`<h2>Your integrated clinical game plan</h2><div class="review-grid"><section><h3>NOTICE</h3><p>${s.notice.map(esc).join('<br>')}</p><p>${esc(s.noticeOwn||'')}</p></section><section><h3>DECIDE</h3><p>${esc(s.aim)}</p><p>${esc(s.rationale)}</p></section><section><h3>GUIDE</h3><p><strong>Opening:</strong> ${esc(s.guide.opening||s.guideOwn.opening)}</p><p><strong>Middle:</strong> ${esc(s.guide.middle||s.guideOwn.middle)}</p><p><strong>Closing:</strong> ${esc(s.guide.closing||s.guideOwn.closing)}</p></section><section><h3>ADAPT</h3><p>${esc(s.adapt||s.adaptOwn)}</p><p><strong>What changed:</strong> ${esc(s.after)}</p></section></div><button class="primary" data-save-game>Save game plan to Playbook</button> <button class="secondary" data-go-advanced="w4-simulation">Enter final simulation</button>`;root.innerHTML=`<div class="advanced-shell">${back(4)}${head(4,'Clinical Mastery Lab','Build a full clinical game plan for Maya, then update it when new information appears.')}<article class="advanced-card"><p class="eyebrow">New client briefing</p><p><strong>Maya, 32:</strong> “I understand why I do what I do, but I keep ending up in the same place. I’m starting to wonder whether therapy is helping.”</p></article><div class="workflow-tabs">${['notice','decide','guide','adapt','review'].map(k=>`<button data-w4-tab="${k}" class="${t===k?'active':''}">${k}</button>`).join('')}</div><article class="tab-panel">${p}<p class="save-status"></p></article></div>`;bindW4(root);commonBindings(root)}
function bindW4(root){const s=state.w4;$$('[data-w4-tab]',root).forEach(b=>b.onclick=()=>{s.tab=b.dataset.w4Tab;save();renderW4()});$$('[data-guide-tab]',root).forEach(b=>b.onclick=()=>{s.guideTab=b.dataset.guideTab;save();renderW4()});if(s.tab==='notice')multi(root,'.choice-list button',s.notice,v=>{s.notice=v;save();renderW4()});if(s.tab==='decide')choose(root,'.choice-list button',s.aim,v=>{s.aim=v;save();renderW4()});if(s.tab==='guide')choose(root,'.choice-list button',s.guide[s.guideTab],v=>{s.guide[s.guideTab]=v;save();renderW4()});if(s.tab==='adapt')choose(root,'.choice-list button',s.adapt,v=>{s.adapt=v;save();renderW4()});input(root,'textarea',(k,v)=>{if(k==='guideOwn')s.guideOwn[s.guideTab]=v;else s[k]=v});$('[data-save-game]',root)?.addEventListener('click',()=>status(root,'Integrated Game Plan added to your Clinical Playbook.'))}

function renderPlaybook(){const root=$('[data-advanced-host="playbook"]'),tab=state.playbookTab||'confidence',blank='—';const content={confidence:`<h2>My Confidence Profile</h2><p>Return to Week 1 whenever you want to revise your focus.</p>`,decision:`<h2>My Decision Map</h2><dl><dt>Relevant facts</dt><dd>${state.w2.facts.map(k=>esc(w2Tabs[k])).join('<br>')||blank}</dd><dt>Working explanation</dt><dd>${esc(state.w2.hypothesis||blank)}</dd><dt>What changed</dt><dd>${esc(state.w2.revision||blank)}</dd><dt>Purposeful move</dt><dd>${esc(state.w2.move||blank)}</dd></dl>`,roadmap:`<h2>My Session Roadmap</h2><dl><dt>Opening</dt><dd>${esc(state.w3.aim||blank)}</dd><dt>Middle</dt><dd>${esc(state.w3.middle||blank)}</dd><dt>Adjustment</dt><dd>${esc(state.w3.after||blank)}</dd><dt>Closing</dt><dd>${state.w3.closing.map(esc).join(' → ')||blank}</dd></dl>`,game:`<h2>My Integrated Game Plan</h2><dl><dt>Notice</dt><dd>${state.w4.notice.map(esc).join('<br>')||blank}</dd><dt>Decide</dt><dd>${esc(state.w4.aim||blank)}</dd><dt>Guide</dt><dd>${['opening','middle','closing'].map(k=>`<strong>${k}:</strong> ${esc(state.w4.guide[k]||state.w4.guideOwn[k]||blank)}`).join('<br>')}</dd><dt>Adapt</dt><dd>${esc(state.w4.adapt||state.w4.adaptOwn||blank)}</dd></dl>`,plan:`<h2>My 30-Day Practice Plan</h2><div class="plan-fields"><label>One skill I want to rehearse<input name="skill" value="${esc(state.plan.skill)}" placeholder="Collaborative focusing questions"></label><label>My rehearsal schedule<input name="schedule" value="${esc(state.plan.schedule)}" placeholder="Twice per week for 5–10 minutes"></label><label>Practice material<input name="material" value="${esc(state.plan.material)}" placeholder="Practice Floor or a simulation replay"></label><label>How I’ll check for change<input name="measure" value="${esc(state.plan.measure)}" placeholder="Can I respond and explain why?"></label><label>If I need support<input name="support" value="${esc(state.plan.support)}" placeholder="Supervision, consultation, or training"></label></div><button class="primary" data-save-plan>Save my plan</button>`}[tab];root.innerHTML=`<div class="advanced-shell">${head('1–4','My Clinical Playbook','Your work from each week, in one place.')}<div class="playbook-tabs">${[['confidence','Confidence Profile'],['decision','Decision Map'],['roadmap','Session Roadmap'],['game','Integrated Game Plan'],['plan','30-Day Plan']].map(([k,l])=>`<button data-playbook-tab="${k}" class="${tab===k?'active':''}">${l}</button>`).join('')}</div><article class="playbook-panel">${content}<p class="save-status"></p></article></div>`;bindPlaybook(root);commonBindings(root)}
function bindPlaybook(root){$$('[data-playbook-tab]',root).forEach(b=>b.onclick=()=>{state.playbookTab=b.dataset.playbookTab;save();renderPlaybook()});input(root,'.plan-fields input',(k,v)=>state.plan[k]=v);$$('[data-evidence]',root).forEach(x=>x.oninput=()=>{state.evidence[x.dataset.evidence]=x.value;save()});$('[data-save-plan]',root)?.addEventListener('click',()=>status(root,'30-day plan saved.'))}

/* Practice Floor reps. Weeks 2–4 follow the Build Master list; the Week 1 reps and any lines marked DRAFT are proposed wording for Tiffany to approve. */
const practiceItems=[
 {id:'w1-quiet',week:1,title:'The Long Silence',line:'You ask a question. The client looks down and says nothing for a long moment.',ask:'What happens inside you, and what would you do with the silence?'},/* DRAFT */
 {id:'w1-praise',week:1,title:'“You’re So Much Better Than My Last Therapist”',line:'“Honestly, you get me way more than anyone I’ve seen before.”',ask:'Notice the pull. What would you say that keeps the focus on the client?'},/* DRAFT */
 {id:'w1-normal',week:1,title:'“Is This Normal?”',line:'“Am I crazy for feeling this way? Just tell me if this is normal.”',ask:'What would you say, and what are you curious about underneath the question?'},/* DRAFT */
 {id:'w2-reassure',week:2,title:'The Reassurance Loop',line:'Taylor says, “Just tell me everything will be okay.”',ask:'What would you say next, and why that move?'},
 {id:'w2-focus',week:2,title:'Picking a Focus When Everything Matters',line:'“My job, my mom, my partner, money… I don’t even know where to start.”',ask:'How would you choose a focus together?'},/* DRAFT line */
 {id:'w2-correct',week:2,title:'The Client Corrects My Hypothesis',line:'“That isn’t what I meant at all.”',ask:'What would you say, and what would you revise?'},
 {id:'w3-notopic',week:3,title:'Client Has No Topic',line:'“I don’t know. Nothing really happened this week.”',ask:'How would you begin finding a destination for today?'},
 {id:'w3-venting',week:3,title:'Twenty Minutes of Venting',line:'The client has described the same conflict for twenty minutes, in more detail each time.',ask:'Deepen or shift? What would you say?'},/* DRAFT line */
 {id:'w3-five',week:3,title:'Five Minutes Remaining',line:'“Wait—there’s one more thing I haven’t told you.”',ask:'How would you respond and still land the session?'},
 {id:'w4-interp',week:4,title:'The Client Corrects My Interpretation',line:'“No. That’s not why I did it. You’re not hearing me.”',ask:'How would you acknowledge the miss and adjust?'},/* DRAFT line */
 {id:'w4-understand',week:4,title:'You Don’t Understand',line:'“I don’t think you understand what this is actually like.”',ask:'What would you say, without defending yourself?'},
 {id:'w4-certainty',week:4,title:'The Client Wants Certainty',line:'“I need you to tell me whether I’m making the right choice.”',ask:'What would you say, and what would you avoid?'},
 {id:'w4-value',week:4,title:'“Is This Even Helping?”',line:'“I’ve been coming for months. I’m not sure this is doing anything.”',ask:'How would you respond with curiosity instead of reassurance?'}/* DRAFT line */
];
function renderPractice(week=0){const root=$('[data-advanced-host="practice-floor"]');const weeks=week?[week]:[1,2,3,4];
 root.innerHTML=`<div class="advanced-shell practice-floor">${week?back(week):''}<header class="advanced-head"><div><p class="eyebrow">${week?`Week ${week} · ${weekVerb[week]} · Optional`:'Optional reps'}</p><h1>Practice Floor</h1><p>${week?'Short moments that use this week’s skill. Say your response out loud first, then write it down.':'Short moments for each week’s skill. Come back whenever you want another rep.'}</p></div></header>
 ${weeks.map(w=>`<section class="practice-week">${week?'':`<h2 class="practice-week-title">Week ${w} · ${weekVerb[w]}</h2>`}<div class="practice-grid">${practiceItems.filter(x=>x.week===w).map(x=>`<article class="practice-card"><h3>${x.title}</h3><blockquote>${x.line}</blockquote><label>${x.ask}<textarea data-practice="${x.id}" placeholder="Your response…">${esc(state.practice[x.id]||'')}</textarea></label><button class="secondary" data-save-practice="${x.id}">Save</button><p class="save-status"></p></article>`).join('')}</div></section>`).join('')}</div>`;
 if(Array.isArray(state.practice))state.practice={};
 $$('[data-practice]',root).forEach(t=>t.oninput=()=>{state.practice[t.dataset.practice]=t.value;save()});$$('[data-save-practice]',root).forEach(b=>b.onclick=()=>status(b.closest('.practice-card'),'Saved.'));commonBindings(root)}

/* Lesson page: video, a reflection that saves, watched state, previous/next, and the lab after lesson 3.
   Reflection prompts are proposed wording for Tiffany to approve. Add a Wistia ID as the 3rd item of a lesson in weekData to embed it. */
const reflectPrompts={
 'w1-1':'When you picture a “confident therapist,” what are they doing? Which part of that is certainty, and which part could you actually practice?',
 'w1-2':'Think of a moment you felt put on the spot (fictional or generalized). What did you feel pulled to do: fix, reassure, explain, or prove?',
 'w1-3':'Which part of P.A.U.S.E. is hardest for you under pressure? What small cue could bring you back to it?',
 'w2-1':'Think of a client story with many topics. What thread might sit underneath them, and what would tell you whether it fits?',
 'w2-2':'Which CLEAR step do you skip when you feel rushed? What would it look like to slow down at that step?',
 'w2-3':'Write one next move for a stuck moment, then the one-sentence reason you’d give a supervisor.',
 'w3-1':'How do you usually open a session? Write how a collaboratively chosen destination might sound in your own words.',
 'w3-2':'What tells you to stay with something versus shift? Name one signal you trust and one you second-guess.',
 'w3-3':'What tends to happen in your last ten minutes? What would landing the session look like, without forcing a breakthrough?',
 'w4-1':'Pick a session choice you still replay. Write what you observed, separately from what you decided it says about you.',
 'w4-2':'When a response misses, what is your first instinct? Write what you might say to acknowledge the impact and adjust.',
 'w4-3':'What is one piece of evidence from these four weeks that your confidence is growing?'
};
function renderLesson(id){const [w,n]=id.slice(1).split('-').map(Number),d=weekData[w],x=d.lessons[n-1],root=$('[data-lesson-host]');if(!root||!x)return;
 const watched=!!state.lessons[id],vid=x[2];
 root.innerHTML=`<div class="advanced-shell lesson-page">${back(w)}<header class="lesson-head"><span class="lesson-num" aria-hidden="true">${n}</span><p class="eyebrow">Week ${w} · Lesson ${n} of 3</p><h1>${italLast(x[0])}</h1><p>${x[1]}</p></header>
 <div class="lesson-video">${vid?`<iframe src="https://fast.wistia.net/embed/iframe/${vid}?videoFoam=true&seo=false" title="${esc(x[0])}" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe>`:`<div class="lesson-video-empty"><span class="lesson-play" aria-hidden="true"></span><small>Lesson video</small></div>`}</div>
 <div class="lesson-steps">${d.lessons.map((l,i)=>`<button type="button" class="${i+1===n?'active':''} ${state.lessons[`w${w}-${i+1}`]?'done':''}" data-open-lesson="w${w}-${i+1}"><span>${i+1}</span>${l[0]}</button>`).join('')}</div>
 <section class="lesson-reflect"><p class="eyebrow">Reflect</p><h2>${reflectPrompts[id]||'What is one idea from this lesson you want to try?'}</h2><textarea data-reflection placeholder="A few honest sentences…">${esc(state.reflections[id]||'')}</textarea><p class="save-status" aria-live="polite"></p></section>
 <nav class="lesson-nav"><button class="secondary" type="button" data-mark-watched>${watched?'Watched ✓':'Mark as watched'}</button>${n<3?`<button class="primary" type="button" data-next-lesson="w${w}-${n+1}">Next lesson →</button>`:`<button class="primary" type="button" data-finish-lessons="${d.labScreen}">Enter the ${d.lab} →</button>`}</nav></div>`;
 const t=$('[data-reflection]',root);let timer;t.oninput=()=>{state.reflections[id]=t.value;clearTimeout(timer);timer=setTimeout(()=>status(root,'Saved'),400)};
 $('[data-mark-watched]',root).onclick=()=>{state.lessons[id]=!state.lessons[id];save();renderLesson(id);renderWeeks()};
 const done=()=>{state.lessons[id]=true;save();renderWeeks()};
 $('[data-next-lesson]',root)?.addEventListener('click',e=>{done();renderLesson(e.currentTarget.dataset.nextLesson);scrollTo({top:0})});
 $('[data-finish-lessons]',root)?.addEventListener('click',e=>{done();show(e.currentTarget.dataset.finishLessons)});
 commonBindings(root)}

function updateProgress(){const lessonCount=Object.values(state.lessons).filter(Boolean).length,simCount=Object.values(state.sims).filter(x=>x.complete).length,labCount=(state.w2.move?1:0)+(state.w3.aim&&state.w3.closing.length?1:0)+(state.w4.adapt?1:0),percent=Math.min(100,Math.round(((lessonCount+simCount+labCount)/15)*100));$('[data-progress-label]').textContent=`${percent}%`;$('[data-progress-bar]').style.width=`${percent}%`}
function validateGraphs(){for(const [key,cfg] of Object.entries(simGraphs))for(const [id,node] of Object.entries(cfg.nodes))for(const [,next] of node[1])if(!cfg.nodes[next])throw new Error(`${key}: ${id} routes to missing ${next}`)}
$$('.side-link[data-screen="practice-floor"]').forEach(b=>b.addEventListener('click',()=>renderPractice(0)));validateGraphs();renderWeeks();renderW2();renderW3();renderW4();renderSim('w2');renderSim('w3');renderSim('w4');renderPlaybook();renderPractice();commonBindings();updateProgress();
})();
